function debounce(fn, delay) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

const bus = {
  handlers: [],
  subscribe(fn) { this.handlers.push(fn); },
  publish(data) { this.handlers.forEach(h => h(data)); }
};
